CREATE POLICY "loja admin read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'loja' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "loja admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'loja' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "loja admin update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'loja' AND public.has_role(auth.uid(),'admin')) WITH CHECK (bucket_id = 'loja' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "loja admin delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'loja' AND public.has_role(auth.uid(),'admin'));